-- V6__dynamic_assessment_enhancements.sql
-- Additive migration for AI-powered Dynamic Skill Assessment

-- 1. Create assessment_attempts table for managing dynamic assessment lifecycles
CREATE TABLE assessment_attempts (
    id                  BIGSERIAL PRIMARY KEY,
    user_id             BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    skill_id            BIGINT NOT NULL REFERENCES skills(id) ON DELETE CASCADE,
    assessment_id       BIGINT REFERENCES skill_assessments(id) ON DELETE SET NULL,
    assignment_id       BIGINT REFERENCES assessment_assignments(id) ON DELETE SET NULL,
    target_level        VARCHAR(30) NOT NULL DEFAULT 'Intermediate',
    current_level       VARCHAR(30) DEFAULT 'Unaware',
    status              VARCHAR(20) NOT NULL DEFAULT 'IN_PROGRESS' CHECK (status IN ('IN_PROGRESS', 'COMPLETED', 'ABANDONED', 'EXPIRED')),
    generation_source   VARCHAR(30) NOT NULL DEFAULT 'FALLBACK' CHECK (generation_source IN ('AI_GENERATED', 'FALLBACK')),
    generation_status   VARCHAR(30) NOT NULL DEFAULT 'SUCCESS' CHECK (generation_status IN ('SUCCESS', 'FALLBACK_TRIGGERED', 'FAILED')),
    generation_error    TEXT,
    score               INT,
    passed              BOOLEAN,
    correct_answers     INT,
    total_questions     INT NOT NULL DEFAULT 0,
    answers_json        TEXT,
    started_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    completed_at        TIMESTAMPTZ
);

CREATE INDEX idx_assessment_attempts_user ON assessment_attempts(user_id);
CREATE INDEX idx_assessment_attempts_skill ON assessment_attempts(skill_id);
CREATE INDEX idx_assessment_attempts_user_status ON assessment_attempts(user_id, status);
CREATE INDEX idx_assessment_attempts_user_skill ON assessment_attempts(user_id, skill_id, started_at DESC);

-- 2. Enhance assessment_questions to link to specific attempts and store question metadata
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS attempt_id BIGINT REFERENCES assessment_attempts(id) ON DELETE CASCADE;
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS difficulty VARCHAR(20) NOT NULL DEFAULT 'MEDIUM';
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS subtopic VARCHAR(100);
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS explanation TEXT;
ALTER TABLE assessment_questions ADD COLUMN IF NOT EXISTS question_order INT NOT NULL DEFAULT 0;

CREATE INDEX idx_assessment_questions_attempt ON assessment_questions(attempt_id);
CREATE INDEX idx_assessment_questions_skill_diff ON assessment_questions(skill_id, difficulty) WHERE attempt_id IS NULL;

-- 3. Enhance assessment_submissions to record generation source and attempt metadata
ALTER TABLE assessment_submissions ADD COLUMN IF NOT EXISTS attempt_id BIGINT REFERENCES assessment_attempts(id) ON DELETE SET NULL;
ALTER TABLE assessment_submissions ADD COLUMN IF NOT EXISTS generation_source VARCHAR(30) NOT NULL DEFAULT 'FALLBACK';
ALTER TABLE assessment_submissions ADD COLUMN IF NOT EXISTS target_level VARCHAR(30);
ALTER TABLE assessment_submissions ADD COLUMN IF NOT EXISTS skill_id BIGINT REFERENCES skills(id) ON DELETE SET NULL;

-- 4. Enhance skill_assessments with skill reference
ALTER TABLE skill_assessments ADD COLUMN IF NOT EXISTS skill_id BIGINT REFERENCES skills(id) ON DELETE SET NULL;

