INSERT INTO assessment_questions (assessment_id, skill_id, question_text, options_json, correct_answer_index, points, difficulty, subtopic, explanation, question_order)
VALUES
(1, 1, 'Which Java interface must be implemented to allow an object to be sorted using Collections.sort() without a custom comparator?', '["Cloneable", "Serializable", "Comparable", "Iterable"]', 2, 1, 'EASY', 'Collections', 'Implementing java.lang.Comparable requires defining compareTo(), which defines the natural ordering of objects.', 0),
(1, 1, 'What is the primary difference between checked and unchecked exceptions in Java?', '["Checked exceptions inherit from RuntimeException", "Checked exceptions must be declared or caught at compile time", "Unchecked exceptions cannot be caught in try-catch", "Checked exceptions are thrown only by the JVM"]', 1, 1, 'MEDIUM', 'Exceptions', 'Checked exceptions (subclasses of Exception excluding RuntimeException) are verified at compile time and must be handled or declared.', 0),
(1, 1, 'In Java, how does the try-with-resources statement guarantee resource cleanup?', '["It requires resources to implement AutoCloseable and calls close() automatically", "It forces the garbage collector to immediately finalize the object", "It wraps every statement in a thread-safe synchronized lock", "It terminates the JVM if a leak is detected"]', 0, 1, 'MEDIUM', 'Resource Management', 'Any object implementing java.lang.AutoCloseable can be used in try-with-resources and will have close() called automatically when the block terminates.', 0),
(1, 1, 'What causes a ConcurrentModificationException when iterating over an ArrayList?', '["Two threads reading from the list simultaneously", "Modifying the list structurally while an Iterator is traversing it without using Iterator.remove()", "Accessing an invalid array index out of bounds", "Passing null to the contains() method"]', 1, 1, 'HARD', 'Concurrency', 'Iterators in standard Java collections are fail-fast; if the underlying list modCount changes without using the iterator own methods, ConcurrentModificationException is thrown.', 0),
(1, 1, 'In Java memory management, where are local primitive variables and object references stored?', '["Metaspace", "The Garbage Collected Heap", "Thread Stack", "Direct Native Memory"]', 2, 1, 'HARD', 'JVM Memory', 'Thread execution stacks store local primitive variables and object references, while the actual object instances reside in the Heap.', 0),
(1, 1, 'Which intermediate Stream operation allows transforming each element into another object in Java 8+?', '["filter()", "map()", "peek()", "reduce()"]', 1, 1, 'EASY', 'Streams', 'The map() intermediate operation applies a Function to each element and returns a new stream of the transformed elements.', 0),
(1, 1, 'What is the purpose of the volatile keyword in Java multithreading?', '["Ensures mutual exclusion like a synchronized block", "Guarantees thread visibility by reading/writing directly to main memory and prevents instruction reordering", "Marks a variable as immutable", "Automatically converts primitive types to atomic wrappers"]', 1, 1, 'HARD', 'Concurrency', 'volatile establishes a happens-before relationship, guaranteeing all threads see the most up-to-date value and preventing specific instruction reorderings.', 0),
(1, 1, 'What is the time complexity of searching for an element in an unsorted ArrayList of size n?', '["O(1)", "O(log n)", "O(n)", "O(n log n)"]', 2, 1, 'EASY', 'Data Structures', 'Searching in an unsorted array list requires a linear scan through the elements, which takes O(n) time.', 0);
INSERT INTO assessment_questions (assessment_id, skill_id, question_text, options_json, correct_answer_index, points, difficulty, subtopic, explanation, question_order)
VALUES
(1, 2, 'Which annotation is a convenience annotation that combines @Configuration, @EnableAutoConfiguration, and @ComponentScan?', '["@SpringBootApplication", "@EnableConfigurationProperties", "@SpringBootConfiguration", "@Controller"]', 0, 1, 'EASY', 'Core Architecture', '@SpringBootApplication encapsulates @Configuration, @EnableAutoConfiguration, and @ComponentScan with standard defaults.', 0),
(1, 2, 'What is the default scope of a Spring bean managed by the ApplicationContext?', '["prototype", "singleton", "request", "session"]', 1, 1, 'EASY', 'Bean Lifecycle', 'By default, Spring beans are singletons: one shared instance per Spring IoC container.', 0),
(1, 2, 'In Spring Data JPA, how does the repository framework derive queries from method names like findByEmailAndStatus?', '["It uses reflection to parse method name keywords into JPQL/SQL AST queries at startup", "It invokes stored procedures matching the name", "It executes full table scans and filters in memory", "It requires explicit XML mapping"]', 0, 1, 'MEDIUM', 'Spring Data', 'Spring Data parses method prefixes and subject keywords (e.g. findBy...And...) into structured criteria queries.', 0),
(1, 2, 'Which annotation should be used to handle exceptions globally across all controllers in Spring MVC?', '["@ExceptionHandler", "@ControllerAdvice", "@ResponseStatus", "@Validated"]', 1, 1, 'MEDIUM', 'Exception Handling', '@ControllerAdvice (or @RestControllerAdvice) allows centralizing exception handling across multiple controller classes.', 0),
(1, 2, 'How does @Transactional manage transaction boundaries in standard Spring Boot applications?', '["By utilizing dynamic bytecode manipulation or CGLIB/JDK dynamic proxies around bean method invocations", "By replacing the JVM garbage collector", "By locking the entire database during method execution", "By making all fields static"]', 0, 1, 'HARD', 'Transactions', 'Spring creates an AOP proxy around @Transactional beans to open, commit, or rollback database transactions upon method completion or runtime exception.', 0),
(1, 2, 'Which HTTP status code is typically returned when a requested resource is created successfully using POST?', '["200 OK", "201 Created", "202 Accepted", "204 No Content"]', 1, 1, 'EASY', 'REST APIs', 'HTTP 201 Created signifies that the request succeeded and resulted in the creation of a new resource.', 0),
(1, 2, 'In Spring Security 6, how are CSRF tokens typically configured for cookie-based stateful sessions?', '["CSRF protection is completely deprecated", "Using CsrfTokenRequestAttributeHandler with CookieCsrfTokenRepository or session storage", "By hardcoding tokens in HTTP GET URLs", "By disabling authentication filters"]', 1, 1, 'HARD', 'Security', 'Spring Security 6 uses CsrfTokenRequestAttributeHandler alongside token repositories to protect against cross-site request forgery.', 0),
(1, 2, 'What does the @Qualifier annotation resolve when injecting dependencies in Spring?', '["It verifies database credentials", "It resolves ambiguity when multiple beans of the same type exist in the container", "It forces lazy initialization of the bean", "It validates bean property constraints"]', 1, 1, 'MEDIUM', 'Dependency Injection', 'When more than one bean matches an autowiring target type, @Qualifier specifies the exact bean name to inject.', 0);
INSERT INTO assessment_questions (assessment_id, skill_id, question_text, options_json, correct_answer_index, points, difficulty, subtopic, explanation, question_order)
VALUES
(1, 3, 'In React, which hook is used to perform side effects such as data fetching or subscriptions?', '["useState", "useEffect", "useMemo", "useContext"]', 1, 1, 'EASY', 'React Hooks', 'useEffect handles side effects including network requests, manual DOM mutations, and event listeners after rendering.', 0),
(1, 3, 'In CSS Flexbox, which property aligns items along the cross axis?', '["justify-content", "align-items", "flex-direction", "flex-wrap"]', 1, 1, 'EASY', 'CSS Layout', 'align-items defines default alignment for items along the cross axis, while justify-content aligns along the main axis.', 0),
(1, 3, 'What is the purpose of the Same-Origin Policy in modern web browsers?', '["To restrict how a document or script loaded from one origin can interact with a resource from another origin", "To speed up DNS resolution across domains", "To compress HTML payloads over HTTP/2", "To enforce strict CSS styling standards"]', 0, 1, 'MEDIUM', 'Browser Security', 'The Same-Origin Policy is a critical security mechanism that isolates potentially malicious documents from accessing sensitive data on other origins.', 0),
(1, 3, 'In React, why should you avoid using array indices as keys when rendering dynamic lists that can be reordered?', '["Keys must be numeric only", "It breaks component state association and causes inefficient DOM reconciliation bugs during reordering or deletion", "React throws a compile-time syntax error", "Array indices consume more memory than UUIDs"]', 1, 1, 'HARD', 'Reconciliation', 'React uses keys to identify which items have changed, moved, or deleted; unstable index keys lead to incorrect component state binding.', 0),
(1, 3, 'What does the HTTP header Cache-Control: no-cache mean?', '["The browser must never store the response on disk", "The response can be stored but must be revalidated with the origin server before reuse", "Caching is enabled for 24 hours", "The server ignores all conditional requests"]', 1, 1, 'MEDIUM', 'HTTP Protocol', 'no-cache allows caching but forces cache validation with the origin server (using ETag or Last-Modified) prior to using the cached copy.', 0),
(1, 3, 'Which JavaScript keyword declares a block-scoped variable that cannot be reassigned?', '["var", "let", "const", "static"]', 2, 1, 'EASY', 'JavaScript', 'const creates an immutable block-scoped binding that cannot be reassigned after declaration.', 0),
(1, 3, 'What is the primary benefit of CSS Grid over Flexbox for complex two-dimensional layouts?', '["Grid is two-dimensional (handling columns and rows simultaneously), whereas Flexbox is primarily one-dimensional", "Grid does not require CSS classes", "Grid works in older browsers without prefixes", "Grid automatically executes JavaScript animations"]', 0, 1, 'MEDIUM', 'CSS Layout', 'CSS Grid is designed for simultaneous two-dimensional row and column control, whereas Flexbox focuses on one-dimensional distribution.', 0),
(1, 3, 'How does the JavaScript Event Loop handle asynchronous Promise callbacks (then/catch)?', '["They are placed in the Microtask queue, which is processed immediately after the current macrotask before rendering", "They are executed on a separate native operating system thread", "They are delayed by a minimum of 10 milliseconds", "They bypass the call stack entirely"]', 0, 1, 'HARD', 'Async JS', 'Promise callbacks are scheduled in the Microtask queue, which runs immediately after synchronous execution and before the next macrotask or repaint.', 0);
INSERT INTO assessment_questions (assessment_id, skill_id, question_text, options_json, correct_answer_index, points, difficulty, subtopic, explanation, question_order)
VALUES
(1, 4, 'Which SQL constraint guarantees that all values in a column are distinct and not null?', '["UNIQUE", "PRIMARY KEY", "FOREIGN KEY", "CHECK"]', 1, 1, 'EASY', 'Constraints', 'A PRIMARY KEY constraint uniquely identifies each record and implicitly enforces NOT NULL and UNIQUE constraints.', 0),
(1, 4, 'What is the main purpose of a database index on a frequently queried column?', '["To encrypt column data at rest", "To speed up data retrieval operations at the expense of slower write operations and extra disk storage", "To automatically normalize database tables", "To prevent foreign key deletions"]', 1, 1, 'EASY', 'Indexing', 'Indexes create optimized search structures (like B-trees) that dramatically accelerate SELECT queries while adding write overhead.', 0),
(1, 4, 'In SQL, what is the difference between TRUNCATE and DELETE statements?', '["TRUNCATE cannot remove all rows", "TRUNCATE is a DDL operation that deallocates data pages quickly without firing row-level triggers, while DELETE is DML", "DELETE cannot be rolled back in a transaction", "TRUNCATE requires a WHERE clause"]', 1, 1, 'MEDIUM', 'Data Manipulation', 'TRUNCATE deallocates table pages quickly and does not activate individual row triggers, whereas DELETE scans and logs individual row deletions.', 0),
(1, 4, 'What phenomenon does the SERIALIZABLE transaction isolation level prevent that REPEATABLE READ may allow?', '["Dirty Reads", "Non-Repeatable Reads", "Phantom Reads / Serialization Anomaly", "Lost Updates"]', 2, 1, 'HARD', 'Transactions', 'SERIALIZABLE prevents phantom reads and concurrency anomalies by ensuring the outcome is equivalent to executing transactions sequentially.', 0),
(1, 4, 'What does the SQL COALESCE function return?', '["The sum of all non-null arguments", "The first non-null expression in its argument list", "The count of distinct rows", "The average of column values"]', 1, 1, 'MEDIUM', 'Functions', 'COALESCE(val1, val2, ...) evaluates arguments in order and returns the first non-null value encountered.', 0),
(1, 4, 'Which clause is used in SQL to combine the result sets of two queries while eliminating duplicate rows?', '["UNION ALL", "UNION", "JOIN", "INTERSECT"]', 1, 1, 'EASY', 'Set Operations', 'UNION combines rows from two queries and filters out duplicates, whereas UNION ALL preserves all duplicates.', 0),
(1, 4, 'In PostgreSQL, which index type is best suited for searching JSONB document keys and values?', '["B-Tree", "GIN (Generalized Inverted Index)", "Hash", "BRIN"]', 1, 1, 'HARD', 'PostgreSQL Specifics', 'GIN indexes are designed for composite values where elements need to be searched within container documents, making them ideal for JSONB and array types.', 0),
(1, 4, 'What is the function of the EXPLAIN ANALYZE command in PostgreSQL?', '["It re-indexes all corrupted tables", "It shows the execution plan generated by the planner and executes the query to report actual run times", "It checks SQL syntax without running the query", "It automatically refactors slow SQL queries"]', 1, 1, 'MEDIUM', 'Query Optimization', 'EXPLAIN ANALYZE displays the optimizer query plan and executes the statement to report actual execution times, loop counts, and memory usage.', 0);
INSERT INTO assessment_questions (assessment_id, skill_id, question_text, options_json, correct_answer_index, points, difficulty, subtopic, explanation, question_order)
VALUES
(1, 5, 'What is the primary objective of a Unit Test?', '["To test the entire application end-to-end with network dependencies", "To verify that a single class or method behaves as expected in isolation", "To evaluate database query response times under heavy load", "To check browser visual rendering"]', 1, 1, 'EASY', 'Unit Testing', 'Unit tests focus on the smallest testable units of software in complete isolation from external systems.', 0),
(1, 5, 'In Mockito, what is the difference between @Mock and @Spy?', '["@Mock creates a complete dummy object where all methods return defaults; @Spy wraps a real instance and executes real methods unless stubbed", "@Mock executes real code while @Spy only mocks interfaces", "@Spy can only be used with static methods", "@Mock requires a database connection"]', 0, 1, 'MEDIUM', 'Mocking', '@Mock produces an empty stub where interactions do nothing unless configured, while @Spy delegates to the real object implementation unless specifically overridden.', 0),
(1, 5, 'What does the Arrange-Act-Assert (AAA) pattern prescribe in test design?', '["Authenticate, Authorize, Audit", "Setup test preconditions, invoke the unit under test, verify the resulting outcome", "Run test, record failure, alert developers", "Automate compile, deploy, test"]', 1, 1, 'EASY', 'Test Structure', 'AAA structures tests into three clear phases: Arrange (inputs/mocks), Act (executing the target behavior), and Assert (verifying the expectations).', 0),
(1, 5, 'In Spring Boot test slicing, what does @WebMvcTest load?', '["The entire Spring Boot ApplicationContext including database connections", "Only the Spring MVC controller layer, security configuration, and related web components with service mocks", "Only the Hibernate JPA entity managers", "Only embedded Kafka message brokers"]', 1, 1, 'MEDIUM', 'Integration Testing', '@WebMvcTest focuses strictly on Spring MVC controllers, Jackson mappers, and filters, keeping test startup fast and isolated from services and DB.', 0),
(1, 5, 'What is Mutation Testing in software quality assurance?', '["Injecting artificial faults into code to verify if existing test suites detect and fail on them", "Fuzzing web forms with random input strings", "Testing database schema migration scripts", "Running tests across multiple operating systems"]', 0, 1, 'HARD', 'Quality Assurance', 'Mutation testing modifies program statements (mutants) to see if existing tests fail (kill the mutant), measuring test suite effectiveness.', 0),
(1, 5, 'What is the purpose of test idempotency?', '["Tests run only once and cannot be re-executed", "A test produces identical results regardless of how many times or in what order it is run", "Tests must execute in parallel across multiple machines", "Tests must generate mock data randomly"]', 1, 1, 'MEDIUM', 'Reliability', 'Idempotent tests are repeatable and free of residual side effects, ensuring they never fail intermittently due to execution order.', 0),
(1, 5, 'In JUnit 5, which annotation replaces JUnit 4 @Before?', '["@BeforeAll", "@BeforeEach", "@SetUp", "@Initialize"]', 1, 1, 'EASY', 'JUnit 5', '@BeforeEach designates a method to execute before each individual test method in the test class.', 0),
(1, 5, 'How do Flaky Tests undermine continuous integration pipelines?', '["They prevent Java source code from compiling", "They produce nondeterministic pass/fail results without code changes, reducing team confidence in test failures", "They delete git branches automatically", "They exhaust database storage space"]', 1, 1, 'HARD', 'CI/CD Best Practices', 'Flaky tests erode developer trust in automated testing because failures cannot be reliably attributed to genuine software regressions.', 0);
INSERT INTO assessment_questions (assessment_id, skill_id, question_text, options_json, correct_answer_index, points, difficulty, subtopic, explanation, question_order)
VALUES
(1, 6, 'What is the command to temporarily shelve uncommitted changes so you can work on another task?', '["git stash", "git drop", "git freeze", "git archive"]', 0, 1, 'EASY', 'Stashing', 'git stash saves modified tracked files and staged changes to a temporary stack and reverts the working directory to HEAD.', 0),
(1, 6, 'What is the difference between git merge and git rebase?', '["Merge records a new commit tying together histories, while rebase replays your commits onto another base commit creating a linear history", "Merge deletes the source branch while rebase preserves it", "Rebase only works with GitHub Pull Requests", "Merge cannot resolve conflicts"]', 0, 1, 'MEDIUM', 'Branching', 'Merge creates a merge commit preserving historical topology, while rebase shifts the entire branch to begin on the new tip for a clean linear history.', 0),
(1, 6, 'What does the HEAD pointer represent in a Git repository?', '["The primary production branch on GitHub", "A reference to the currently checked-out commit or branch tip in the working directory", "The first commit ever made in the repository", "The master index file in .git"]', 1, 1, 'EASY', 'Core Git Concepts', 'HEAD is Git pointer to the current snapshot or branch you are working on in your local working tree.', 0),
(1, 6, 'Under what circumstances should you avoid using git push --force on a shared branch?', '["When you want to update documentation", "When other developers have based work on the remote commits, as force pushing rewrites history and can destroy their work", "When switching between SSH and HTTPS remotes", "When committing large image files"]', 1, 1, 'HARD', 'Collaboration', 'Force pushing rewrites remote commit history, which can orphan or overwrite commits that team members have pulled and built upon.', 0),
(1, 6, 'Which command shows a concise one-line history of recent commits in Git?', '["git status -s", "git log --oneline", "git show --summary", "git diff --stat"]', 1, 1, 'EASY', 'Inspection', 'git log --oneline displays each commit on a single line with its abbreviated SHA-1 hash and commit message.', 0),
(1, 6, 'How does Git handle file content storage internally?', '["As delta diffs per line of code across every version", "As SHA-1/SHA-256 addressed immutable blob objects stored in .git/objects", "As encrypted zip files per directory", "As SQL relational records in SQLite"]', 1, 1, 'HARD', 'Internals', 'Git stores file snapshots as content-addressable blob objects indexed by their cryptographic hash in the object store.', 0),
(1, 6, 'What is a detached HEAD state in Git?', '["The repository is corrupted and unusable", "The working tree is checked out directly to a specific commit rather than a named local branch", "The remote origin repository is offline", "A merge conflict has occurred"]', 1, 1, 'MEDIUM', 'Branching', 'A detached HEAD occurs when checking out a specific commit hash, tag, or remote branch directly; new commits made in this state are not attached to any branch.', 0),
(1, 6, 'Which command allows picking a specific commit from one branch and applying it onto your current branch?', '["git clone", "git cherry-pick", "git fetch --single", "git graft"]', 1, 1, 'MEDIUM', 'History Editing', 'git cherry-pick <commit-hash> copies the changes introduced by that specific commit and records a new commit on the active branch.', 0);
INSERT INTO assessment_questions (assessment_id, skill_id, question_text, options_json, correct_answer_index, points, difficulty, subtopic, explanation, question_order)
VALUES
(1, 7, 'What is the worst-case time complexity of searching for an element in an unbalanced Binary Search Tree (BST)?', '["O(1)", "O(log n)", "O(n)", "O(n^2)"]', 2, 1, 'EASY', 'Trees', 'An unbalanced BST can degenerate into a linear linked list where searching takes O(n) time.', 0),
(1, 7, 'Which data structure is primarily used by graph traversal algorithms for Breadth-First Search (BFS)?', '["Stack", "Queue", "Max Heap", "Disjoint Set"]', 1, 1, 'EASY', 'Graphs', 'BFS explores neighbor nodes level-by-level using a First-In, First-Out (FIFO) Queue.', 0),
(1, 7, 'In a Min-Heap with n elements, what is the time complexity of extracting the minimum element?', '["O(1)", "O(log n)", "O(n)", "O(n log n)"]', 1, 1, 'MEDIUM', 'Heaps', 'Extracting the min root requires replacing it with the last element and heapifying down, taking O(log n) time.', 0),
(1, 7, 'What is a key difference between an Array and a Singly Linked List regarding random element access?', '["Arrays provide O(1) random access via index arithmetic, whereas Linked Lists require O(n) sequential traversal", "Linked lists provide O(1) random access while arrays require O(n)", "Arrays require dynamic pointer dereferencing", "Linked lists store contiguous memory blocks"]', 0, 1, 'EASY', 'Arrays vs Lists', 'Arrays occupy contiguous memory allowing constant-time index lookups, while linked lists must be traversed node by node.', 0),
(1, 7, 'How does a Trie (Prefix Tree) achieve efficient retrieval of strings?', '["By sorting strings into a balanced AVL tree", "By sharing common prefix node paths across keys so lookup time depends on key length rather than collection size", "By computing MD5 hashes for each word", "By storing characters in a binary min-heap"]', 1, 1, 'MEDIUM', 'Tries', 'Tries structure strings along character edge paths, providing O(k) search and prefix lookup time where k is word length.', 0),
(1, 7, 'What technique is used in open-addressing Hash Tables to resolve hash collisions when two keys hash to the same bucket?', '["Chaining via linked lists", "Linear or Quadratic Probing / Double Hashing to find an empty slot", "Immediate table resizing", "Discarding the older key"]', 1, 1, 'HARD', 'Hashing', 'Open addressing stores all elements inside the hash table array and probes alternative slot locations when collisions occur.', 0),
(1, 7, 'What guarantees that an AVL Tree remains strictly balanced with O(log n) search, insertion, and deletion times?', '["The height difference (balance factor) between left and right subtrees of any node never exceeds 1", "Every node has exactly two children", "The tree is rebuilt after every 10 operations", "Nodes are sorted by insertion order"]', 0, 1, 'HARD', 'Self-Balancing Trees', 'AVL trees enforce a balance factor of -1, 0, or 1 at every node, executing tree rotations immediately when invariants are violated.', 0),
(1, 7, 'Which data structure is ideal for tracking both the current maximum element and constant time push/pop operations?', '["Standard array", "Stack accompanied by an auxiliary max-tracking stack", "Single singly linked list", "Hash set"]', 1, 1, 'MEDIUM', 'Stack Applications', 'Maintaining an auxiliary stack that records running maximums allows retrieving the max in O(1) without degrading O(1) push and pop operations.', 0);
INSERT INTO assessment_questions (assessment_id, skill_id, question_text, options_json, correct_answer_index, points, difficulty, subtopic, explanation, question_order)
VALUES
(1, 8, 'What is the core principle behind the Divide and Conquer algorithm strategy?', '["Greedily picking the best immediate step", "Breaking a problem into smaller independent subproblems, solving them recursively, and combining their solutions", "Trying all possible combinations until one works", "Pre-computing all possible answers in a lookup table"]', 1, 1, 'EASY', 'Algorithm Strategies', 'Divide and conquer breaks down a problem into subproblems of the same type, solves them recursively, and merges results (e.g. Merge Sort).', 0),
(1, 8, 'What distinguishes Dynamic Programming from standard recursion?', '["Dynamic Programming uses iterative loops only", "Dynamic Programming identifies overlapping subproblems and caches intermediate results (memoization/tabulation) to avoid redundant recalculation", "Dynamic Programming can only solve sorting problems", "Dynamic Programming runs in O(1) space"]', 1, 1, 'MEDIUM', 'Dynamic Programming', 'Dynamic programming optimizes recursion by caching solutions to overlapping subproblems, eliminating exponential duplicate work.', 0),
(1, 8, 'When applying the Two-Pointers pattern to find two numbers that sum to a target in an array, what prerequisite is necessary?', '["The array must contain only positive integers", "The array must be sorted", "The array size must be a power of two", "All numbers must be unique"]', 1, 1, 'MEDIUM', 'Two Pointers', 'The classic two-pointer technique (left and right converging) requires a sorted array so moving pointers monotonically increases or decreases the sum.', 0),
(1, 8, 'What is the primary characteristic of a Greedy Algorithm?', '["It reconsiders previous choices when a dead end is encountered", "It makes the locally optimal choice at each step hoping it leads to a global optimum", "It computes all permutations before selecting an answer", "It requires exponential memory"]', 1, 1, 'EASY', 'Greedy Approach', 'Greedy algorithms choose the best immediate option without backtracking, which produces global optimums when the greedy-choice property holds.', 0),
(1, 8, 'What is the time complexity of the Binary Search algorithm on a sorted array of n elements?', '["O(1)", "O(log n)", "O(n)", "O(n log n)"]', 1, 1, 'EASY', 'Search Algorithms', 'Binary search divides the search space in half with each comparison, yielding O(log n) logarithmic time complexity.', 0),
(1, 8, 'What technique is used in Backtracking algorithms to abandon candidate solutions that cannot lead to a valid outcome?', '["Memoization", "Pruning", "Hashing", "Pivoting"]', 1, 1, 'HARD', 'Backtracking', 'Pruning terminates exploration along a search branch as soon as constraints show the branch cannot possibly produce a valid solution.', 0),
(1, 8, 'In the Sliding Window pattern, what advantage does it provide over nested brute-force loops for subarray problems?', '["It converts O(n^2) nested scans into an O(n) linear scan by dynamically expanding and contracting window bounds", "It eliminates the need for variable declaration", "It compresses the input array", "It operates concurrently across CPU cores"]', 0, 1, 'MEDIUM', 'Sliding Window', 'Sliding window maintains state across a moving range, avoiding recalculation of the overlapping elements and reducing complexity to linear O(n).', 0),
(1, 8, 'Which property must a problem possess for a Greedy algorithm to guarantee a globally optimal solution?', '["Non-overlapping subproblems and quadratic bounds", "Optimal substructure and the greedy-choice property", "Strictly binary inputs", "Independent random distributions"]', 1, 1, 'HARD', 'Algorithm Design', 'A greedy algorithm is optimal if and only if local optimal choices lead to global optimality (greedy choice) and subproblem optimal solutions compose the global solution (optimal substructure).', 0);
